function maxSinVecinos(pagos) {
  let prev2 = 0, prev1 = 0;
  for (const p of pagos) {
    const actual = Math.max(prev1, prev2 + p);
    prev2 = prev1;
    prev1 = actual;
  }
  return prev1;
}

